/**
 * SYNTHETIC RTA test fixtures, built in memory.
 *
 * Every file here is generated by the tests themselves with the xlsx library
 * and zip.js. Layouts are made up for the test (or reuse only the column
 * NAMES the parsers already match on); they prove how the importer handles
 * containers, encodings and dates — nothing about what real CAMS / KFintech
 * files contain. Identifiers are fake: PAN AAAPA1234A, folio 9999999/99.
 */

import * as XLSX from "xlsx";
import { ZipWriter, Uint8ArrayWriter, Uint8ArrayReader, configure } from "@zip.js/zip.js";

configure({ useWebWorkers: false });

export const FAKE_PAN = "AAAPA1234A";
export const FAKE_PAN_2 = "BBBPB5678B";
export const FAKE_FOLIO = "9999999/99";

/** 2 Oct 2024, 31 Mar 2025, 1 Jan 2000 as Excel (1900-system) serials. */
export const SERIAL = { oct2_2024: 45567, mar31_2025: 45747, jan1_2000: 36526 } as const;

export type CellSpec = string | number | { date: number; fmt?: string };

/** A one-sheet workbook. `{ date: serial }` cells are numbers carrying a date format, as Excel stores them. */
export function makeWorkbook(rows: CellSpec[][], bookType: XLSX.BookType, opts: { date1904?: boolean; sheetName?: string } = {}): Buffer {
  const aoa = rows.map((r) => r.map((c) => (typeof c === "object" ? c.date : c)));
  const ws = XLSX.utils.aoa_to_sheet(aoa);
  rows.forEach((r, R) =>
    r.forEach((c, C) => {
      if (typeof c === "object") {
        const cell = ws[XLSX.utils.encode_cell({ r: R, c: C })];
        cell.t = "n";
        cell.z = c.fmt ?? "dd-mm-yyyy";
      }
    })
  );
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, opts.sheetName ?? "Data");
  if (opts.date1904) wb.Workbook = { ...(wb.Workbook ?? {}), WBProps: { date1904: true } };
  return XLSX.write(wb, { type: "buffer", bookType }) as Buffer;
}

export async function makeZip(
  entries: Array<{ name: string; data: string | Uint8Array; directory?: boolean }>,
  opts: { password?: string; zipCrypto?: boolean } = {}
): Promise<Uint8Array> {
  const writer = new ZipWriter(new Uint8ArrayWriter(), opts.password ? { password: opts.password, zipCrypto: !!opts.zipCrypto } : undefined);
  for (const e of entries) {
    if (e.directory) {
      await writer.add(e.name, undefined, { directory: true });
      continue;
    }
    const bytes = typeof e.data === "string" ? new TextEncoder().encode(e.data) : e.data;
    await writer.add(e.name, new Uint8ArrayReader(bytes));
  }
  return writer.close();
}

/**
 * A CFB container shaped like a password-protected .xlsx: `EncryptionInfo` +
 * `EncryptedPackage` streams. The stream CONTENTS are junk — it only needs to
 * look encrypted to the detector and be unreadable to SheetJS.
 */
export function makeEncryptedOoxmlLookalike(): Buffer {
  const cfb = XLSX.CFB.utils.cfb_new();
  XLSX.CFB.utils.cfb_add(cfb, "/EncryptionInfo", Buffer.from([0x04, 0x00, 0x04, 0x00, 0x40, 0x00, 0x00, 0x00, 0x3c, 0x3f, 0x78, 0x6d]));
  XLSX.CFB.utils.cfb_add(cfb, "/EncryptedPackage", Buffer.alloc(4096, 0x5a));
  return Buffer.from(XLSX.CFB.write(cfb, { type: "buffer" }) as Buffer);
}

export const CSV_FEED = `Folio,Scheme,Amount\n${FAKE_FOLIO},Synthetic Equity Fund,1000\n`;
